//! Fixtures are generated by the pinned Python oracle, not Rust itself.
use goa2_core::{
    codec::StateEnvelope,
    geometry::{BoardGeometry, MovementQuery, TileSpec},
};
use serde::Deserialize;
use serde_json::Value;

#[derive(Deserialize)]
struct MovementCase {
    name: String,
    tiles: Vec<TileSpec>,
    queries: Vec<MovementQuery>,
    expected: Vec<Vec<bool>>,
    stateful_expected: Vec<Vec<bool>>,
}
#[derive(Deserialize)]
struct MovementCorpus {
    cases: Vec<MovementCase>,
}
#[test]
fn all_map_and_generated_movement_verdicts_match_python_bfs() {
    let corpus: MovementCorpus =
        serde_json::from_str(include_str!("../../../tests/fixtures/movement.json")).unwrap();
    let mut checks = 0;
    for case in corpus.cases {
        let (board, occupancy) = BoardGeometry::compile(&case.tiles).unwrap();
        assert_eq!(case.queries.len(), case.expected.len());
        for (i, (query, expected)) in case.queries.iter().zip(&case.expected).enumerate() {
            assert_eq!(
                board.movement_paths(&occupancy, query),
                *expected,
                "{} query {}",
                case.name,
                i
            );
            assert_eq!(
                board.stateful_paths(&occupancy, query),
                case.stateful_expected[i],
                "{} stateful query {}",
                case.name,
                i
            );
            checks += expected.len();
        }
    }
    assert!(
        checks > 100_000,
        "a reduced corpus must not silently replace all-map coverage"
    );
}
#[test]
fn full_states_aliases_tokens_overrides_and_continuations_roundtrip() {
    let corpus: Value =
        serde_json::from_str(include_str!("../../../tests/fixtures/states.json")).unwrap();
    for case in corpus["cases"].as_array().unwrap() {
        let envelope: StateEnvelope = serde_json::from_value(case["envelope"].clone()).unwrap();
        envelope.validate().unwrap();
        assert_eq!(
            envelope.materialize().unwrap(),
            case["expected"],
            "{}",
            case["name"]
        );
        assert_eq!(serde_json::to_value(&envelope).unwrap(), case["envelope"]);
        assert_eq!(
            serde_json::to_string(&envelope).unwrap(),
            serde_json::to_string(&case["envelope"]).unwrap(),
            "object insertion order must survive the outer boundary"
        );
        assert!(
            envelope
                .require_native_execution()
                .unwrap_err()
                .contains("unsupported native transition")
        );
    }
}
